import React, { useEffect, useState } from "react";
import RetailerOrdersTable from "./RetailerOrdersTable";
import useApi from "../../../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import { getLoggedInUser } from "../../../../helpers/authUtils";
import { deleteDraftOrder } from "../../../../helpers/wholesalerHelpers";

import { YesNoModal } from "../../../../components";
import "react-toastify/dist/ReactToastify.css";
import { ToastContainer, toast } from "react-toastify";
import RetailerOrderStatusFormModal from "./RetailerOrderStatusFormModal";
import wholesalersApi from "../../../../api/wholesalers/wholesalersApi";
const closedOrderColumns = [
  { name: "Reference", uid: "reference_number" },
  { name: "Status", uid: "status" },
  { name: "Is Paid", uid: "is_paid" },
  { name: "Payment Method", uid: "payment_method_title" },
  { name: "Retailer", uid: "retailer_title" },
  { name: "Wholesaler", uid: "wholesaler_title" },
  { name: "Total Discount", uid: "order_discount_total" },
  { name: "Order Total", uid: "order_price_total" },
  { name: "Order Origin", uid: "order_origin" },
  { name: "Time Created", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function RetailerOrdersList() {
  const [openDraftOrderFormModal, setopenDraftOrderFormModal] = useState(false);
  const [openClosedtFormModal, setopenClosedFormModal] = useState(false);
  const navigate = useNavigate();
  const [selectedRetailerOrder, setselectedRetailerOrder] = useState();
  const [retailerOrders, setRetailerOrders] = useState([]);
  const [closedOrdersdata, setClosedOrdersData] = useState([]);
  const [draftOrdersdata, setDraftOrdersData] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const retailerOrdersActionsApi = useApi(
    wholesalersApi.wholesaleRetailerOrdersAction
  );
  const [selected, setSelected] = React.useState("login");
  const [draftRetailerOrders, setdraftRetailerOrders] = useState([]);
  const [draftOrderToDelete, setdraftOrderToDelete] = useState();

  const [showYesNoModal, setshowYesNoModal] = useState(false);
  const [selectedDates, setSelectedDates] = useState();
  const [paymentMethods, setpaymentMethods] = useState([]);
  const [retailerOrderStatusOptions, setretailerOrderStatusOptions] = useState([
    {
      label: "DISPATCHED",
      value: "DISPATCHED",
    },

    {
      label: "PROCESSING",
      value: "PROCESSING",
    },
  ]);

  const [openRetailerOrderStatusModal, setopenRetailerOrderStatusModal] =
    useState(false);

  // const { state } = useLocation();
  // console.log("State at list", state);

  const [user, setUser] = useState();
  const loggedInUser = getLoggedInUser();

  useEffect(() => {
    // setdraftRetailerOrders(retrieveDraftRetailerOrders(state.id));
  }, []);

  useEffect(() => {
    console.log("Dates", selectedDates);
  }, [selectedDates]);
  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  const getEntityCustomerOrders = async (user) => {
    setRetailerOrders([]);
    await retailerOrdersActionsApi.request({
      action: "GetEntityRetailerOrders",
    });
  };

  const getEntityCustomerOrdersByDate = async () => {
    setRetailerOrders([]);
    const dates = {
      action: "GetEntityRetailerOrdersByWholesaler",
      // wholesaler: state.id,
      from_date: selectedDates ? selectedDates[0] : "",
      to_date: selectedDates ? selectedDates[1] : "",
    };
    console.log("dst", dates);
    await retailerOrdersActionsApi.request(dates);
  };

  useEffect(() => {
    console.log("drafts", draftRetailerOrders);
  }, [draftRetailerOrders]);

  useEffect(() => {
    getEntityCustomerOrders();
  }, []);

  useEffect(() => {
    if (updated === true) {
      getEntityCustomerOrders();
    }
  }, [updated]);

  useEffect(() => {
    if (selectedDates) {
      getEntityCustomerOrdersByDate();
    }
    console.log("dates changed");
  }, [selectedDates]);

  useEffect(() => {
    getEntityCustomerOrders();
    // setdraftRetailerOrders(retrieveDraftRetailerOrders(state.id));
  }, [openDraftOrderFormModal]);

  const handleEditAction = (item) => {
    setErrors([]);

    setUpdated(false);

    setselectedRetailerOrder(item);
    setmodalTitle(`${item.title}`);
    setopenRetailerOrderStatusModal(true);
  };

  const handleDetailsAction = (item) => {
    console.log("To invoice", item);
    navigate(`/marketplace/wholesalers/invoice/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    // navigate(`/retailers/departments/delete/${item.id}`)
  };

  useEffect(() => {
    if (retailerOrdersActionsApi.data && retailerOrdersActionsApi.data.length) {
      setRetailerOrders(retailerOrdersActionsApi.data);
    }

    console.log("retailerOrdersActionsApi.data", retailerOrdersActionsApi.data);
  }, [retailerOrdersActionsApi.data]);

  useEffect(() => {}, [openDraftOrderFormModal, openClosedtFormModal]);

  //Filtering data
  useEffect(() => {
    setClosedOrdersData(retailerOrders);
  }, [retailerOrders]);

  useEffect(() => {
    setDraftOrdersData(draftRetailerOrders);
  }, [draftRetailerOrders]);

  const handleFilterClosedOrders = (e) => {
    const search_param = e;

    if (
      retailerOrders &&
      retailerOrders.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setClosedOrdersData(
        retailerOrders.filter((x) =>
          x.customer_name.toLowerCase().includes(search_param)
        )
      );
    } else {
      setClosedOrdersData(retailerOrdersActionsApi.data);
    }
  };

  const handleFilterDraftOrders = (e) => {
    const search_param = e;

    if (
      draftRetailerOrders &&
      draftRetailerOrders.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setDraftOrdersData(
        draftRetailerOrders.filter((x) =>
          x.customer_name.toLowerCase().includes(search_param)
        )
      );
    } else {
      setDraftOrdersData(draftRetailerOrders);
    }
  };

  const [errors, setErrors] = useState([]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        return toast.error(x);
      });
    }
  }, [errors]);

  const handleDeleteDraftOrder = async () => {
    if (draftOrderToDelete) {
      const res = await deleteDraftOrder(draftOrderToDelete.draft_id);
      if (res) {
        setdraftOrderToDelete(null);
        // console.log('resss', res)
        setshowYesNoModal(false);
        // setdraftRetailerOrders(retrieveDraftRetailerOrders(state.id));
      }
    }
  };

  const handleReceiveOrder = () => {};

  return (
    <div>
      <ToastContainer position="bottom-center" theme="colored" />
      <YesNoModal
        showModal={showYesNoModal}
        header="Delete Draft Order"
        content="Action is irreversible!"
        setShowModal={setshowYesNoModal}
        yesAction={handleDeleteDraftOrder}
      />

      <RetailerOrderStatusFormModal
        errors={errors}
        setErrors={setErrors}
        openRetailerOrderStatusModal={openRetailerOrderStatusModal}
        setopenRetailerOrderStatusModal={setopenRetailerOrderStatusModal}
        retailerOrderStatusOptions={retailerOrderStatusOptions}
        selectedRetailerOrder={selectedRetailerOrder}
        updated={updated}
        setUpdated={setUpdated}
      />

      <RetailerOrdersTable
        data={retailerOrders}
        columns={closedOrderColumns}
        editAction={handleEditAction}
        receiveAction={handleReceiveOrder}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        handleFilter={handleFilterClosedOrders}
        selectedDates={selectedDates}
        setSelectedDates={setSelectedDates}
      />
    </div>
  );
}

export default RetailerOrdersList;
