import React, { useEffect, useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
} from "@heroui/react";

import * as Yup from "yup";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
} from "../../../../components";
import { useFormik } from "formik";
import useApi from "../../../../hooks/useApi";
import wholesalersApi from "../../../../api/wholesalers/wholesalersApi";
import { useStateContext } from "../../../../contexts/ContextProvider";
import { toast } from "react-toastify";

export default function RetailerOrderStatusFormModal({
  openRetailerOrderStatusModal,
  setopenRetailerOrderStatusModal,
  retailerOrderStatusOptions,
  selectedRetailerOrder,
  errors,
  setErrors,
  updated,
  setUpdated,
}) {
  const [selectedStatus, setselectedStatus] = useState();
  const { currentColor } = useStateContext();

  const retailerOrderPaymentApi = useApi(
    wholesalersApi.wholesaleRetailerOrdersAction
  );

  const handleUpdateRetailerOrder = async (data) => {
    await retailerOrderPaymentApi.request(data);
  };

  useEffect(() => {
    console.log("retailerOrderPaymentApi.data", retailerOrderPaymentApi.data);

    if (retailerOrderPaymentApi.data) {
      if (
        retailerOrderPaymentApi.data.errors &&
        retailerOrderPaymentApi.data.errors.length
      ) {
        setErrors(retailerOrderPaymentApi.data.errors);
      }
    }

    if (
      retailerOrderPaymentApi.data &&
      retailerOrderPaymentApi.data.response_code === 0
    ) {
      toast.success(retailerOrderPaymentApi.data.response_message);
      setUpdated(true);
      setopenRetailerOrderStatusModal(false);
    }
  }, [retailerOrderPaymentApi.data]);

  const formik = useFormik({
    initialValues: {
      status: "",
    },

    validationSchema: Yup.object({
      status: Yup.string().required().label("Status"),
    }),
    onSubmit: (values, { resetForm }) => {
      console.log("VALZ", values);

      const data = {
        action: "UpdateRetailerOrder",
        retailer_order_details: {
          retailer_order_id: selectedRetailerOrder.id,
          status: values.status,
        },
      };
      console.log("data", data);
      handleUpdateRetailerOrder(data);
    },
  });

  const handleSelect = (item) => {
    console.log("item", item);
    formik.setFieldValue("status", item.value);
    setselectedStatus(item.label);
  };

  return (
    <>
      <Modal isOpen={openRetailerOrderStatusModal} placement="center">
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader className="flex flex-col gap-1 text-center text-large font-bold">
                Select Order Status
              </ModalHeader>
              <ModalBody>
                <CustomForm
                  layout="vertical"
                  handleFinish={formik.handleSubmit}
                  className=" flex flex-col justify-center items-center w-full my-7"
                >
                  <CustomFormItem
                    touched={formik.touched.status}
                    error={formik.errors.status}
                  >
                    <CustomSelectReactSelect
                      required={true}
                      id="status"
                      name="status"
                      onChange={(e) => handleSelect(e)}
                      placeholder="Select order status"
                      size="large"
                      type="text"
                      options={retailerOrderStatusOptions}
                    />
                  </CustomFormItem>

                  <div className="w-full items-center mt-2">
                    <Button
                      style={{ background: currentColor }}
                      className="w-full rounded-md self-center"
                      color="primary"
                      type="submit"
                    >
                      Confirm
                    </Button>
                  </div>
                </CustomForm>
              </ModalBody>

              <ModalFooter>
                <Button
                  color="danger"
                  variant="flat"
                  onPress={() => setopenRetailerOrderStatusModal(false)}
                >
                  Cancel
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    </>
  );
}
